    /** Revoke, disable and delete are applied by the real Admin SDK; the real verifier must refuse each. */
    private void remoteRefusals() throws Exception {
        checkpoint = "REAL_ADMIN_REVOKE_DISABLE_DELETE_REFUSED";
        var id = create( "Refusal", "refusal" );
        bind( id );
        var uid = plannedUid( id );
        String token = login( "refusal" );
        long tokenReceivedNs = System.nanoTime();
        expect( "GET", "/api/auth/me", token, null, null, 200 );
        var claims = unverifiedRevocationClaims( token );
        assertThat( uid.equals( claims.get( "sub" ) ) )
                .as( "REVOKE_SUB: o sub deve corresponder ao UID que será revogado." ).isTrue();
        assertThat( claims.get( "iat" ) instanceof Number && claims.get( "auth_time" ) instanceof Number )
                .as( "REVOKE_CLAIMS: iat e auth_time devem ser numéricos." ).isTrue();
        long iat = ((Number) claims.get( "iat" )).longValue();
        long authTime = ((Number) claims.get( "auth_time" )).longValue();
        // O validSince do Admin SDK usa o relógio local; o desvio do host não pode decidir o teste por acaso.
        // Instant.now() usa o sistema, independentemente do Clock do Spring.
        awaitRevocationClock( iat, authTime );
        admin.revokeRefreshTokens( uid );
        Thread.sleep( 1500 );
        long validAfterMs = expectRevokedToken( token, uid, iat, authTime );
        awaitRenewalClock( iat, authTime, tokenReceivedNs, validAfterMs );
        String renewed = login( "refusal" );
        var renewedClaims = unverifiedRevocationClaims( renewed );
        assertThat( renewedClaims.get( "iat" ) instanceof Number )
                .as( "REVOKE_CLAIMS: iat do token renovado deve ser numérico." ).isTrue();
        long renewedIat = ((Number) renewedClaims.get( "iat" )).longValue();
        assertThat( Math.multiplyExact( renewedIat, 1000L ) >= validAfterMs )
                .as( "CLOCK_SKEW: o token renovado deve alcançar o corte remoto; iat=" + renewedIat + " auth_time=" + authTime + " validAfterMs=" + validAfterMs + " epochLocal=" + Instant.now().getEpochSecond() + "." )
                .isTrue();
        expect( "GET", "/api/auth/me", renewed, null, null, 200 );
        admin.setDisabled( uid, true );
        expectSettled( "after-disable", "GET", "/api/auth/me", renewed, 401 );
        admin.setDisabled( uid, false );
        expectSettled( "after-enable", "GET", "/api/auth/me", renewed, 200 );
        assertThat( directory.delete( uid ) ).as( "real Admin delete" ).isTrue();
        expectSettled( "after-delete", "GET", "/api/auth/me", renewed, 401 );
        passed();
    }

    private void awaitRevocationClock( long iat, long authTime ) throws InterruptedException {
        long startedNs = System.nanoTime();
        long localEpoch = Instant.now().getEpochSecond();
        while ( localEpoch <= Math.max( iat, authTime ) + 1 ) {
            if ( System.nanoTime() - startedNs >= TimeUnit.SECONDS.toNanos( 30 ) ) {
                throw new AssertionError( "CLOCK_SKEW: o relógio local não superou a emissão em até 30 s; iat=" + iat + " auth_time=" + authTime + " epochLocal=" + localEpoch + "." );
            }
            Thread.sleep( 200 );
            localEpoch = Instant.now().getEpochSecond();
        }
    }

    private void awaitRenewalClock( long iat, long authTime, long tokenReceivedNs, long validAfterMs ) throws InterruptedException {
        // Se o host estiver adiantado, o tempo monotônico desde a recepção dá um piso para o relógio remoto.
        long startedNs = System.nanoTime();
        long validSince = Instant.ofEpochMilli( validAfterMs ).getEpochSecond();
        while ( iat + TimeUnit.NANOSECONDS.toSeconds( System.nanoTime() - tokenReceivedNs ) <= validSince ) {
            if ( System.nanoTime() - startedNs >= TimeUnit.SECONDS.toNanos( 30 ) ) {
                throw new AssertionError( "CLOCK_SKEW: o relógio remoto não alcançou o corte em até 30 s; iat=" + iat + " auth_time=" + authTime + " validAfterMs=" + validAfterMs + " epochLocal=" + Instant.now().getEpochSecond() + "." );
            }
            Thread.sleep( 200 );
        }
    }

    /** Apenas leitura diagnóstica do payload; não substitui a verificação do token. */
    private Map<?, ?> unverifiedRevocationClaims( String token ) {
        try {
            var segments = token.split( "\\.", -1 );
            assertThat( segments.length ).as( "REVOKE_CLAIMS: o JWT deve ter três segmentos." ).isEqualTo( 3 );
            var payload = new String( Base64.getUrlDecoder().decode( segments[1] ), StandardCharsets.UTF_8 );
            return JSON.fromString( payload, Map.class );
        } catch ( IOException | IllegalArgumentException failure ) {
            // Não propagar payload, token ou a causa do parser para o reporter.
            throw new AssertionError( "REVOKE_CLAIMS: não foi possível ler o payload do JWT." );
        }
    }

    private long expectRevokedToken( String token, String uid, long iat, long authTime ) throws Exception {
        var healthyAdmin = FirebaseAuth.getInstance( application.getBean( FirebaseApp.class ) );
        long validAfterMs;
        try {
            validAfterMs = healthyAdmin.getUser( uid ).getTokensValidAfterTimestamp();
        } catch ( com.google.firebase.auth.FirebaseAuthException failure ) {
            throw FirebaseRealTestProject.translate( "getUser", failure );
        }
        long iatMs = Math.multiplyExact( iat, 1000L );
        long authTimeMs = Math.multiplyExact( authTime, 1000L );
        String direct = "ACCEPTED";
        try {
            healthyAdmin.verifyIdToken( token, true );
        } catch ( com.google.firebase.auth.FirebaseAuthException failure ) {
            if ( failure.getErrorCode() == com.google.firebase.ErrorCode.RESOURCE_EXHAUSTED ) {
                throw FirebaseRealTestProject.translate( "verifyIdToken", failure );
            }
            var code = failure.getAuthErrorCode();
            direct = code == null ? "NO_AUTH_ERROR_CODE" : code.name();
        }
        String port = "ACCEPTED";
        try {
            application.getBean( IdTokenVerifier.class ).verify( token );
        } catch ( FirebaseAuthException failure ) {
            port = failure.reason().name();
        }
        int http = -1;
        try {
            // Mesmo limite de expectSettled; 503 interrompe a espera sem nova tentativa.
            for ( int attempt = 0; attempt < 30 && http != 401 && http != 503; attempt++ ) {
                if ( attempt > 0 ) {
                    Thread.sleep( 500 );
                }
                http = send( api, "GET", "/api/auth/me", token, null, null ).statusCode();
            }
        } finally {
            System.out.println( "T029 REVOKE_DIAG iat=" + iat + " auth_time=" + authTime + " validAfterMs=" + validAfterMs + " direct=" + direct + " port=" + port + " http=" + http );
        }

        assertThat( validAfterMs > authTimeMs && validAfterMs > iatMs )
                .as( "REVOKE_PRECONDITION: o corte remoto deve superar auth_time e iat; iat=" + iat + " auth_time=" + authTime + " validAfterMs=" + validAfterMs + " iatMs=" + iatMs + " authTimeMs=" + authTimeMs + "." )
                .isTrue();
        assertThat( direct ).as( "PROVIDER_ACCEPTS_REVOKED: o Admin direto deve rejeitar o token revogado." )
                .isNotEqualTo( "ACCEPTED" );
        assertThat( port ).as( "SDK_PORT_ACCEPTS_REVOKED: a porta do SDK deve rejeitar o token revogado." )
                .isNotEqualTo( "ACCEPTED" );
        assertThat( http ).as( "REVOKE_HTTP_STATUS: o provedor deve estar disponível." ).isNotEqualTo( 503 );
        assertThat( http ).as( http == 200
                ? "HTTP_PATH_ACCEPTS_REVOKED: GET /api/auth/me aceitou o token rejeitado pelo Admin e pela porta."
                : "REVOKE_HTTP_STATUS: GET /api/auth/me deve retornar 401 após a revogação." ).isEqualTo( 401 );
        assertThat( direct ).as( "REVOKE_DIRECT_RESULT: o Admin deve informar REVOKED_ID_TOKEN." )
                .isEqualTo( AuthErrorCode.REVOKED_ID_TOKEN.name() );
        assertThat( port ).as( "REVOKE_PORT_RESULT: a porta deve informar INVALID_TOKEN." )
                .isEqualTo( FirebaseAuthException.Reason.INVALID_TOKEN.name() );
        return validAfterMs;
    }

    private void remoteAckRace() throws Exception {
        checkpoint = "NATIVE_ADMIN_CREATE_ACK_CAS_INFLIGHT";
        var id = create( "Remote race", "remote-race" );
        var reached = new CountDownLatch( 1 );
        var release = new CountDownLatch( 1 );
        var forwarding = new FirebaseAdminGateway() {

            public User getUser( String uid ) {
                return admin.getUser( uid );
            }

            public User createUser( String uid, String email, String name ) {
                var created = admin.createUser( uid, email, name );
                reached.countDown();
                try {
                    if ( !release.await( 20, TimeUnit.SECONDS ) )
                        throw new IllegalStateException( "RACE_TIMEOUT" );
                } catch ( InterruptedException failure ) {
                    Thread.currentThread().interrupt();
                    throw new IllegalStateException( "RACE_INTERRUPTED" );
                }
                return created;
            }

            public void setDisabled( String uid, boolean disabled ) {
                admin.setDisabled( uid, disabled );
            }

            public void revokeRefreshTokens( String uid ) {
                admin.revokeRefreshTokens( uid );
            }

            public String passwordResetLink( String email ) {
                throw new UnsupportedOperationException();
            }

        };
        var worker = new JdbcIdentityCommandWorker( jdbc, application.getBean( "firebaseSecurityTransactions", TransactionTemplate.class ), application.getBean( SecurityEventSink.class ), application.getBean( "firebaseSecurityDataSource", DataSource.class ), forwarding, application.getBean( Clock.class ), Duration.ofMinutes( 2 ), catalog );
        try (var executor = Executors.newSingleThreadExecutor()) {
            var pending = executor.submit( worker::runOnce );
            try {
                assertThat( reached.await( 20, TimeUnit.SECONDS ) ).as( "real Admin CREATE reached before ACK" )
                        .isTrue();
                var uid = jdbc.sql( "SELECT cd_uid_planejado FROM security.usuario WHERE id_usuario=:id" )
                        .param( "id", id ).query( String.class ).single();
                assertThat( admin.getUser( uid ).email() ).isEqualTo( namespace.email( "remote-race" ) );
                assertNamespaced( uid );
                // Deliberately adversarial SQL writer bypasses the service advisory lock.
                // This is the actual persisted-version CAS boundary, with real Admin forwarding.
                jdbc.sql( "UPDATE security.usuario SET nr_versao_identidade=nr_versao_identidade+1," + "dt_fim=now() WHERE id_usuario=:id" ).param( "id", id ).update();
            } finally {
                release.countDown();
            }
            assertThat( pending.get( 20, TimeUnit.SECONDS ) ).isTrue();
        }
        assertThat( jdbc.sql( "SELECT cd_estado FROM security.comando_identidade WHERE id_usuario=:id" + " AND cd_tipo='CREATE'" ).param( "id", id ).query( String.class ).single() ).isEqualTo( "OBSOLETE" );
        assertThat( jdbc.sql( "SELECT count(*) FROM security.usuario_identidade WHERE id_usuario=:id" )
                .param( "id", id ).query( Long.class ).single() ).isZero();
        FirebaseRealTestProject.setPassword( realAdmin, plannedUid( id ), password );
        expect( "GET", "/api/auth/me", login( "remote-race" ), null, null, 403 );
        passed();
    }

    private void threadCleanup() throws Exception {
        checkpoint = "NATIVE_SERVLET_REUSED_THREAD_SUCCESS_DENIAL_EXCEPTION_CLEANUP";
        assertThat( tomcatProtocol().getMaxThreads() ).as( "segregated cleanup phase worker limit" ).isOne();
        Observation.requests.clear();
        assertThat( expect( "GET", "/api/tenant-scope-probe/" + SAME_ID, bobToken, "alpha", null, 200 ) )
                .contains( "Alpha" ).doesNotContain( "Beta" );
        expect( "GET", "/api/auth/context", aliceToken, "beta", null, 403 );
        expect( "GET", "/api/tenant-scope-probe/not-a-uuid", bobToken, "alpha", null, 400 );
        assertThat( Observation.requests ).hasSize( 3 ).allSatisfy( observation -> {
            assertThat( observation.beforeClean() ).as( "thread initial state" ).isTrue();
            assertThat( observation.afterClean() ).as( "security/tenant/actor/transaction final state" ).isTrue();
        } );
        assertThat( Observation.requests.stream().map( ObservedRequest::thread ).distinct().count() )
                .as( "actual servlet thread reused across success, denial and MVC exception" ).isOne();
        assertThat( Observation.requests.stream().map( ObservedRequest::status ).toList() )
                .containsExactly( 200, 403, 400 );
        System.out.println( "T029 WORKER_PHASE cleanup max=1 observedThreads=1 statuses=200,403,400" );
        passed();
    }

    private org.apache.coyote.AbstractProtocol<?> tomcatProtocol() {
        var server = (org.springframework.boot.tomcat.TomcatWebServer) ((WebServerApplicationContext) application)
                .getWebServer();
        return (org.apache.coyote.AbstractProtocol<?>) server.getTomcat().getConnector().getProtocolHandler();
    }

    private record ObservedRequest(long thread, boolean beforeClean, boolean afterClean, int status) {

    }

    /** Explicitly installed in the child only; observes the real chain and poisons its input. */
    @TestConfiguration(proxyBeanMethods = false)
    public static class Observation {

        @Bean
        ScopeProbe scopeProbe() {
            return new ScopeProbe();
        }

        private static final ConcurrentLinkedQueue<ObservedRequest> requests = new ConcurrentLinkedQueue<>();
        private static final Clock clock = Clock.tickMillis( java.time.ZoneOffset.UTC );

        @Bean
        @org.springframework.context.annotation.Primary
        public Clock t029Clock() {
            return clock;
        }

        @Bean
        public FilterRegistrationBean<OncePerRequestFilter> t029ThreadObserver() {
            var registration = new FilterRegistrationBean<OncePerRequestFilter>();
            registration.setOrder( Ordered.HIGHEST_PRECEDENCE );
            registration.setFilter( new OncePerRequestFilter() {

                protected void doFilterInternal( HttpServletRequest request, HttpServletResponse response, FilterChain chain ) throws ServletException, IOException {
                    boolean before = clean();
                    JpaTenantContext.setCurrentTenant( "beta" );
                    MDC.put( "actorId", "t029-poisoned-actor" );
                    SecurityContextHolder.getContext().setAuthentication( new UsernamePasswordAuthenticationToken( "t029-poisoned-user", null, List.of() ) );
                    try {
                        chain.doFilter( request, response );
                    } finally {
                        requests.add( new ObservedRequest( Thread.currentThread().threadId(), before, clean(), response.getStatus() ) );
                    }
                }

                private boolean clean() {
                    return JpaTenantContext.current().isEmpty()
                            && SecurityContextHolder.getContext().getAuthentication() == null
                            && MDC.get( "actorId" ) == null
                            && !TransactionSynchronizationManager.isActualTransactionActive()
                            && TransactionSynchronizationManager.getResourceMap().isEmpty();
                }

            } );
            return registration;
        }

