        @br.com.gems.security.authorization.TenantEndpoint
        @org.springframework.security.access.prepost.PreAuthorize("hasRole('CONSULTAR_MEMBERSHIP')")
        @io.swagger.v3.oas.annotations.Operation(summary = "Test-only tenant scope probe")
        public Map<String, String> read( @org.springframework.web.bind.annotation.PathVariable UUID id ) {
            String label = (String) entityManager.createNativeQuery( "SELECT nm_label FROM scope_probe WHERE id_probe=:id" ).setParameter( "id", id ).getSingleResult();
            return Map.of( "name", label );
        }

    }

}

