    for (let i = 0; i < 8; i++) await Promise.resolve();
  };
  async function ready() {
    change(user);
    token.resolve('token-one');
    await tick();
    http.expectOne(environment.apiBaseUrl + '/auth/me').flush(me);
    await tick();
    const switching = auth.selectTenant('alpha');
