    pending.resolve('old-alpha');
    await alpha;
    await tick();
    http.expectNone(environment.apiBaseUrl + '/auth/context');
    expect(auth.currentTenant()?.alias).toBe('beta');
    expect(auth.loading()).toBe(false);
