  it.each(['new-uid', 'old-uid'])(
    'naoDeveRepetirNavegacao_quandoObserverELoginAntigosChegamAposIntencaoNovaComUID%s',
    async (uid) => {
      const fixture = TestBed.createComponent(LoginComponent);
